//https://leetcode.com/problems/count-number-of-distinct-integers-after-reverse-operations/
class Solution {
public:
    int countDistinctIntegers(vector<int>& nums) {
        int len = nums.size();
        unordered_set<int> s;
        for(auto n: nums){
            s.insert(n);
            string str = to_string(n);
            reverse(str.begin(), str.end());
            n = stoi(str);
            s.insert(n);
        }

        return (int)s.size();
    }
};

